def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def normalize_email(value):
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")

        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in ("0", "1"):
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]

        if len(value) == 4 and value.isdigit():
            value = "0" + value

        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value and (value.isupper() or value.islower()):
            return value.title()
        return value

    def normalize_source(value):
        return value.strip().lower()

    def normalize_tags(value):
        return [
            tag.strip().lower()
            for tag in re.split(r"[;,]", value)
            if tag.strip()
        ]

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized_rows = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        # Rows without either valid contact method cannot participate.
        if not email and not phone:
            continue

        normalized_rows.append({
            "input_index": input_index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "tags": normalize_tags(row["tags"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "updated_dt": parse_updated(row["updated"]),
            "source": normalize_source(row["source"]),
        })

    count = len(normalized_rows)
    parent = list(range(count))
    size = [1] * count

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if size[left_root] < size[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        size[left_root] += size[right_root]

    email_owner = {}
    phone_last_name_owner = {}

    for index, row in enumerate(normalized_rows):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = index
            else:
                union(index, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = phone_last_name_owner.get(key)
            if previous is None:
                phone_last_name_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index in range(count):
        groups.setdefault(find(index), []).append(index)

    def pick_field(group, field):
        candidates = [
            normalized_rows[index]
            for index in group
            if normalized_rows[index][field]
        ]

        if not candidates:
            return ""

        chosen = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["input_index"],
            ),
        )
        return chosen[field]

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(
            normalized_rows[index]["input_index"] for index in group
        ),
    )

    output = []

    for group in ordered_groups:
        group_rows = [normalized_rows[index] for index in group]
        tags = sorted({
            tag
            for row in group_rows
            for tag in row["tags"]
        })
        latest_updated = max(row["updated_dt"] for row in group_rows)

        output.append({
            "first_name": pick_field(group, "first_name"),
            "last_name": pick_field(group, "last_name"),
            "zip": pick_field(group, "zip"),
            "email": pick_field(group, "email"),
            "phone": pick_field(group, "phone"),
            "source": pick_field(group, "source"),
            "tags": ";".join(tags),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group_rows) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
        })

    return output
